-- Read-only final state. Arena owns the Practice functions it replaces.
WITH arena AS (-- Exact ledger, function, RLS and privilege checks. No business data.
WITH checks(name,ok) AS (
 SELECT 'ledger' AS name,EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105000000' AND name='arena_practice_integration' AND cardinality(statements)=1 AND md5(statements[1])='436e441fb7a6b67212e0ae29144a8fd3') AS ok
 UNION ALL SELECT 'arena_practice_pool',coalesce((SELECT md5(prosrc)='24d37c9858a1eca7b832bfef13eaed57' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.arena_practice_pool()')),false)
 UNION ALL SELECT 'arena_practice_payload',coalesce((SELECT md5(prosrc)='1d2ec5917555d2ae38fe2b79ec258721' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.arena_practice_payload(uuid)')),false)
 UNION ALL SELECT 'arena_practice_catalog',coalesce((SELECT md5(prosrc)='e56dca827e1b1c4486d301558dceb676' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.arena_practice_catalog()')),false)
 UNION ALL SELECT 'arena_practice_next_question',coalesce((SELECT md5(prosrc)='776bd662dfe6de0dbe2028235237f3f2' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.arena_practice_next_question(uuid,integer[],integer,integer,boolean)')),false)
 UNION ALL SELECT 'arena_practice_submit_answer',coalesce((SELECT md5(prosrc)='cee734d1360b17e801b34b3d2aa01fb5' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.arena_practice_submit_answer(uuid,integer)')),false)
 UNION ALL SELECT 'get_question_practice_statistics',coalesce((SELECT md5(prosrc)='9e8e446314cac5bcd8a4398e194a610c' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_question_practice_statistics(uuid)')),false)
 UNION ALL SELECT 'question_practice_signals',coalesce((SELECT md5(prosrc)='e82793792defebad26b50f3ff762fa54' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_signals()')),false)
 UNION ALL SELECT 'submit_question_practice_v2',coalesce((SELECT md5(prosrc)='a6570dc31bd7d8e624c9e24e7ab7c7c9' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)')),false)
 UNION ALL SELECT 'start_question_practice_in_scope',coalesce((SELECT md5(prosrc)='0b1b830bd593aed968cc9db2113e80c0' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.start_question_practice_in_scope(uuid,uuid,uuid)')),false)
 UNION ALL SELECT 'question_practice_topic_status',coalesce((SELECT md5(prosrc)='7d125708ca02f1842e021a1db227e8f2' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_topic_status(uuid)')),false)
 UNION ALL SELECT 'question_practice_continuous_pool',coalesce((SELECT md5(prosrc)='a9b4a84055366ea253d42dd08a6c31af' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_pool(uuid)')),false)
 UNION ALL SELECT 'question_practice_continuous_state',coalesce((SELECT md5(prosrc)='5349d7f67d6125355fa8473bcc238c37' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_continuous_state(uuid)')),false)
 UNION ALL SELECT 'question_practice_snapshot',coalesce((SELECT md5(prosrc)='83a3d2378a85df7d085d14c919847dad' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot(uuid)')),false)
 UNION ALL SELECT 'list_question_practice_attempts',coalesce((SELECT md5(prosrc)='0b7c74bfad137b0c0374d0a7e360a2a2' AND prosecdef AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.list_question_practice_attempts(boolean)')),false)
 UNION ALL SELECT 'arena_practice_catalog_permissions',has_function_privilege('authenticated','public.arena_practice_catalog()','EXECUTE') AND NOT has_function_privilege('anon','public.arena_practice_catalog()','EXECUTE')
 UNION ALL SELECT 'arena_practice_next_question_permissions',has_function_privilege('authenticated','public.arena_practice_next_question(uuid,integer[],integer,integer,boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.arena_practice_next_question(uuid,integer[],integer,integer,boolean)','EXECUTE')
 UNION ALL SELECT 'arena_practice_submit_answer_permissions',has_function_privilege('authenticated','public.arena_practice_submit_answer(uuid,integer)','EXECUTE') AND NOT has_function_privilege('anon','public.arena_practice_submit_answer(uuid,integer)','EXECUTE')
 UNION ALL SELECT 'get_question_practice_statistics_permissions',has_function_privilege('authenticated','public.get_question_practice_statistics(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.get_question_practice_statistics(uuid)','EXECUTE')
 UNION ALL SELECT 'arena_practice_pool_private',NOT has_function_privilege('authenticated','public.arena_practice_pool()','EXECUTE') AND NOT has_function_privilege('anon','public.arena_practice_pool()','EXECUTE')
 UNION ALL SELECT 'arena_practice_payload_private',NOT has_function_privilege('authenticated','public.arena_practice_payload(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.arena_practice_payload(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_signals_private',NOT has_function_privilege('authenticated','public.question_practice_signals()','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_signals()','EXECUTE')
 UNION ALL SELECT 'start_question_practice_in_scope_private',NOT has_function_privilege('authenticated','public.start_question_practice_in_scope(uuid,uuid,uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.start_question_practice_in_scope(uuid,uuid,uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_topic_status_private',NOT has_function_privilege('authenticated','public.question_practice_topic_status(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_topic_status(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_continuous_pool_private',NOT has_function_privilege('authenticated','public.question_practice_continuous_pool(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_continuous_pool(uuid)','EXECUTE')
 UNION ALL SELECT 'question_practice_continuous_state_private',NOT has_function_privilege('authenticated','public.question_practice_continuous_state(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_continuous_state(uuid)','EXECUTE')
 UNION ALL SELECT 'issues_private',NOT has_table_privilege('authenticated','public.arena_practice_issues','SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('anon','public.arena_practice_issues','SELECT,INSERT,UPDATE,DELETE') AND (SELECT relrowsecurity FROM pg_class WHERE oid='public.arena_practice_issues'::regclass)
 UNION ALL SELECT 'source_constraint',EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.question_practice_sessions'::regclass AND conname='arena_practice_context')
) SELECT jsonb_build_object('all_checks_pass',bool_and(ok),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS arena_practice_verification FROM checks), source AS (SELECT (EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.save_question_bank_drafts(jsonb)') AND md5(replace(prosrc,E'\r',''))='b5b637db4e84aa4e59989781931c26f5') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.update_question_bank_draft_metadata(uuid,uuid,text,jsonb)') AND md5(replace(prosrc,E'\r',''))='9ee58df274c0e5ced38aae588e8571d0') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.question_bank_content_issues(uuid,uuid)') AND md5(replace(prosrc,E'\r',''))='ee312839e62d85504beafaef696efcda')) AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105020000' AND name='question_bank_legacy_arena_source' AND cardinality(statements)=1 AND md5(statements[1])='819f451763686ddcaadb5e79b0e845c7') AND NOT has_function_privilege('authenticated','public.question_bank_legacy_arena_source(jsonb,text)','EXECUTE') AND NOT has_function_privilege('anon','public.question_bank_legacy_arena_source(jsonb,text)','EXECUTE') AND EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.question_versions'::regclass AND conname='question_versions_source_page_kind' AND convalidated) AS all_checks_pass), checks(name,ok) AS (
 SELECT 'arena_latest_functions_rls_grants',(SELECT (arena_practice_verification->>'all_checks_pass')::boolean FROM arena)
 UNION ALL SELECT 'legacy_source_rpc_and_ledger',(SELECT all_checks_pass FROM source)
 UNION ALL SELECT 'legacy_helper_body_and_context',EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.question_bank_legacy_arena_source(jsonb,text)') AND md5(prosrc)='2d58bf06b6af111ea375f65a5fad7fd6' AND prosecdef AND provolatile='s' AND proconfig @> ARRAY['search_path=public, extensions','TimeZone=UTC'])
 UNION ALL SELECT 'continuous_ledger',EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261104000000' AND name='question_practice_continuous' AND cardinality(statements)=1 AND md5(statements[1])='5812dd9d82c6474144ed67d24d83da65')
 UNION ALL SELECT 'continuous_columns',(SELECT count(*)=2 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_sessions' AND column_name IN ('mode','ended_at'))
 UNION ALL SELECT 'continuous_ended_trigger',EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='question_practice_reject_ended' AND tgrelid='public.question_practice_attempts'::regclass AND tgenabled='O')
 UNION ALL SELECT 'native_page_nullable',EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_versions' AND column_name='source_page' AND is_nullable='YES')
 UNION ALL SELECT 'legacy_tables_retained',to_regclass('public.arena_questions') IS NOT NULL AND to_regclass('public.arena_question_issues') IS NOT NULL
) SELECT jsonb_build_object('all_checks_pass',bool_and(coalesce(ok,false)),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS final_verification FROM checks;
